/* Player-owned identity; generated by this demo, never read from the game ROM. */
(function(root){
 function normalize(p){if(!p||!Number.isInteger(p.id)||p.id<0||p.id>65535||!Number.isFinite(Date.parse(p.startedAt)))return null;return {id:p.id,nature:Number.isInteger(p.nature)&&p.nature>=0&&p.nature<25?p.nature:0,startedAt:new Date(p.startedAt).toISOString(),playSeconds:Math.max(0,Math.min(3599999,Number(p.playSeconds)||0))};}
 function create(now=Date.now(),random=Math.random){return {id:Math.floor(random()*65536),nature:0,startedAt:new Date(now).toISOString(),playSeconds:0};}
 root.TrainerProfile={normalize,create};if(typeof module!=='undefined')module.exports={normalize,create};
})(typeof window!=='undefined'?window:globalThis);
